package cn.local.gaokao;
import java.nio.file.*;
/** Independent numerical oracle generated by running the pinned upstream TypeScript, not this port. */
public final class FsrsMathCheck {
    static int checks;
    static void close(double a,double b,String label){if(!Double.isFinite(a)||Math.abs(a-b)>Math.max(1e-7,Math.abs(b)*1e-11))throw new AssertionError(label+": "+a+" != "+b);checks++;}
    public static void main(String[] args)throws Exception{
        int vectors=0;
        for(String row:Files.readAllLines(Paths.get(args[0]))){if(row.startsWith("#")||row.trim().isEmpty())continue;String[] v=row.split("\\t");double s=Double.parseDouble(v[0]),d=Double.parseDouble(v[1]),elapsed=Double.parseDouble(v[2]),retention=Double.parseDouble(v[4]);int grade=Integer.parseInt(v[3]);
            Fsrs.Memory old=s==0?null:new Fsrs.Memory(s,d),next=Fsrs.next(old,elapsed,grade);close(next.stability,Double.parseDouble(v[5]),"stability "+vectors);close(next.difficulty,Double.parseDouble(v[6]),"difficulty "+vectors);close(old==null?1:Fsrs.retrievability(old,elapsed),Double.parseDouble(v[7]),"retrievability "+vectors);
            if(Fsrs.interval(next,retention)!=Integer.parseInt(v[8]))throw new AssertionError("interval "+vectors);checks++;vectors++;
        }
        for(int grade:new int[]{0,5}){boolean rejected=false;try{Fsrs.next(null,0,grade);}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("invalid grade");checks++;}
        for(double r:new double[]{0,-1,Double.NaN,Double.POSITIVE_INFINITY,1.1}){boolean rejected=false;try{Fsrs.interval(new Fsrs.Memory(2,5),r);}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("invalid retention");checks++;}
        System.out.println("PASS "+checks+" FSRS math checks against "+vectors+" upstream vectors.");
    }
}
